module apple_distance #(\n    parameter GRID_R = 8,\n    parameter GRID_S = 8,\n    parameter MAX_TREES = 24,\n    parameter COORD_BITS = 4,  // Coordinates 1-8\n    parameter DIST_BITS = 7,   // Max squared distance 98\n    parameter TREE_IDX_BITS = 5\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire load_en,        // Load initial tree (pulse high)\n    input wire process,        // Process query (pulse high)\n    input wire [COORD_BITS-1:0] r,\n    input wire [COORD_BITS-1:0] s,\n    output reg [DIST_BITS-1:0] distance,\n    output reg done,\n    output reg full\n);\n\n// Tree storage: parallel arrays for row and column\nreg [COORD_BITS-1:0] tree_r [0:MAX_TREES-1];\nreg [COORD_BITS-1:0] tree_s [0:MAX_TREES-1];\nreg [TREE_IDX_BITS-1:0] num_trees;\n\n// FSM states\nreg [1:0] state;\nlocalparam IDLE = 2'b00;\nlocalparam COMPUTE = 2'b01;\nlocalparam UPDATE = 2'b10;\n\n// Computation registers\nreg [TREE_IDX_BITS-1:0] tree_index;\nreg [DIST_BITS-1:0] current_min;\nreg [COORD_BITS-1:0] query_r, query_s;\n\n// Combinational distance calculation for current tree\nwire [COORD_BITS-1:0] current_tree_r = tree_r[tree_index];\nwire [COORD_BITS-1:0] current_tree_s = tree_s[tree_index];\nwire [COORD_BITS-1:0] diff_r = (query_r >= current_tree_r) ? \n                                (query_r - current_tree_r) : \n                                (current_tree_r - query_r);\nwire [COORD_BITS-1:0] diff_s = (query_s >= current_tree_s) ? \n                                (query_s - current_tree_s) : \n                                (current_tree_s - query_s);\nwire [6:0] current_dist = (diff_r * diff_r) + (diff_s * diff_s);\n\n// State machine and tree management\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        num_trees <= 0;\n        done <= 0;\n        full <= 0;\n        distance <= 0;\n        tree_index <= 0;\n        current_min <= {DIST_BITS{1'b1}};\n    end else begin\n        done <= 0;\n        full <= (num_trees >= MAX_TREES);\n        \n        case (state)\n            IDLE: begin\n                if (load_en && !full) begin\n                    // Load initial tree\n                    tree_r[num_trees] <= r;\n                    tree_s[num_trees] <= s;\n                    num_trees <= num_trees + 1;\n                end else if (process && !full && num_trees > 0) begin\n                    // Start query processing\n                    query_r <= r;\n                    query_s <= s;\n                    tree_index <= 0;\n                    current_min <= {DIST_BITS{1'b1}};\n                    state <= COMPUTE;\n                end\n            end\n            \n            COMPUTE: begin\n                if (tree_index < num_trees) begin\n                    // Update minimum distance\n                    if (current_dist < current_min) begin\n                        current_min <= current_dist;\n                    end\n                    tree_index <= tree_index + 1;\n                end else begin\n                    // All trees processed\n                    state <= UPDATE;\n                end\n            end\n            \n            UPDATE: begin\n                // Add query position as new tree\n                if (!full) begin\n                    tree_r[num_trees] <= query_r;\n                    tree_s[num_trees] <= query_s;\n                    num_trees <= num_trees + 1;\n                end\n                // Output result\n                distance <= current_min;\n                done <= 1;\n                state <= IDLE;\n            end\n        endcase\n    end\nend\n\nendmodule